column19:
=if(and(O3="",Q3=""),"",
trim(join(char(10),
let(entries,transpose(split(join(",",O3,Q3),", "&char(10))),
let(
 construct_names,iferror(filter(entries,not(regexmatch(entries,"^[odagms]\d+$"))),"none"),
 IDs,iferror(filter(entries,regexmatch(entries,"^[odagms]\d+$")),"none"),
let(
  construct_statuses,
  if(construct_names<>"none",byrow(construct_names,lambda(name,iferror(index(Registry_Status,xmatch(name,Registry_Construct_name)),"Construct not found?"))),""),
  IDs_statuses,
  if(IDs<>"none",byrow(IDs,lambda(ID,let(x,GET_STATUS_BY_ID(ID),if(AND(x<>"",x<>FALSE),x,"Invalid ID "&ID&"?")))),""),
byrow({flatten(construct_names,IDs),flatten(construct_statuses,IDs_statuses)},lambda(row,iferror(if(index(row,1)<>"none",index(row,1)&": "&index(row,2),""))))
))))))
